"""Regenerate the generated files under docs/architecture/.

Run via `make docs`. Executes inside the backend container, where /app is the
backend dir and /docs is the repo's docs/ mount. Reads the FastAPI route
table.

Outputs: api/routes.md (endpoint inventory) under docs/architecture/.
"""

import argparse
import sys
from pathlib import Path

# The script lives in backend/scripts/docs/ — put the backend dir on sys.path
# so `import app.*` works regardless of the invocation cwd.
sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

MD_HEADER = (
    "<!-- GENERATED by `make docs` (backend/scripts/docs/generate.py). Do not edit by hand. -->\n"
)


def _write(out_dir: Path, rel: str, body: str) -> Path:
    path = out_dir / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    # The H1 must lead the file: MkDocs only derives a page's nav title from
    # an H1 when nothing (not even an HTML comment) precedes it. Keep the
    # generated-marker comment on line 3 instead of line 1.
    title, _, rest = body.partition("\n")
    path.write_text(f"{title}\n\n{MD_HEADER}\n{rest.lstrip()}")
    return path


# OpenAPI path-item keys that aren't HTTP methods.
_NON_METHOD_KEYS = {"summary", "description", "parameters", "servers", "$ref"}


def generate_routes(out_dir: Path) -> Path:
    """Emit api/routes.md — the API inventory, from the OpenAPI spec.

    app.openapi() is the stable surface here: app.routes nests included
    routers as opaque _IncludedRouter objects rather than flat routes.
    """
    from app.main import app

    lines = [
        "# Routes",
        "",
        "The full machine-readable spec is served at `/openapi.json`.",
        "",
        "| Method | Path | Handler | Tags | Summary |",
        "|---|---|---|---|---|",
    ]
    for path, item in sorted(app.openapi()["paths"].items()):
        for method, op in sorted(item.items()):
            if method in _NON_METHOD_KEYS:
                continue
            handler = op.get("operationId", "—")
            tags = ", ".join(op.get("tags") or []) or "—"
            summary = op.get("summary") or ""
            lines.append(f"| {method.upper()} | `{path}` | `{handler}` | {tags} | {summary} |")
    return _write(out_dir, "api/routes.md", "\n".join(lines) + "\n")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "out_dir",
        nargs="?",
        default="/docs/architecture",
        help="output directory (default: /docs/architecture, the mounted repo docs/)",
    )
    out_dir = Path(parser.parse_args().out_dir)

    print(f"wrote {generate_routes(out_dir)}")


if __name__ == "__main__":
    main()
